reproduce it in thirty seconds:

CREATE TABLE users (id int);
CREATE TABLE blocked (user_id int);
INSERT INTO users VALUES (1), (2), (3);
INSERT INTO blocked VALUES (1), (NULL);

SELECT * FROM users WHERE id NOT IN (SELECT user_id FROM blocked);
-- returns zero rows. user 2 and 3 vanished.

create table users (id int, name text);
create table logs (user_id int);

insert into users values (1, 'alice'), (2, 'bob'), (3, 'carol');
insert into logs values (1), (NULL);

delete from users where id not in (select user_id from logs);

The fix: use NOT EXISTS. It treats NULL as a value that simply does not match.

delete from users u where not exists (select 1 from logs l where l.user_id = u.id);

This deletes only bob and carol. Alice stays because her id exists in logs.

create table orders (id int, status text);
create table cancelled (order_id int);
insert into orders values (1,'open'),(2,'shipped');
insert into cancelled values (1), (NULL);
select * from orders where id not in (select order_id from cancelled);
-- returns nothing, not the shipped row

select * from orders o where not exists (select 1 from cancelled c where c.order_id = o.id);
-- returns the shipped row as intended
NOT EXISTS is null-safe by design. Works the same in Postgres, MySQL, SQL Server, Oracle.
